import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { message } from 'antd';
import { authAPI } from '../services/api';

interface User {
  id: string;
  email?: string;
  username?: string;
  name?: string;
  role?: string;
}

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 检查本地存储的token
    const token = localStorage.getItem('token');
    if (token) {
      // 如果有token，从localStorage获取用户名或使用默认值
      const savedUsername = localStorage.getItem('username') || 'admin';
      setUser({ id: '1', username: savedUsername, role: 'administrator' });
    }
    setLoading(false);
  }, []);

  const login = async (username: string, password: string): Promise<boolean> => {
    try {
      setLoading(true);
      const response = await authAPI.login(username, password);
      
      if (response.data && response.data.access_token) {
        localStorage.setItem('token', response.data.access_token);
        localStorage.setItem('username', username); // 保存用户名
        if (response.data.refresh_token) {
          localStorage.setItem('refresh_token', response.data.refresh_token);
        }
        // 保存真实的登录用户名
        setUser({ id: '1', username, role: 'administrator' });
        message.success('登录成功');
        return true;
      } else {
        message.error('登录失败');
        return false;
      }
    } catch (error: any) {
      console.error('Login error:', error);
      // 处理 axios 错误响应
      let errorMessage = '登录失败，请检查用户名和密码';
      
      if (error.response && error.response.data) {
        // 后端返回的错误信息
        errorMessage = error.response.data.message || error.response.data.msg || error.response.data.error || errorMessage;
      } else if (error.message) {
        errorMessage = error.message;
      }
      
      message.error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const logout = async () => {
    try {
      // 调用后端退出登录接口
      await authAPI.logout();
    } catch (error) {
      console.error('Logout error:', error);
      // 即使后端接口失败，也要清除本地数据
    } finally {
      // 清除本地存储的所有认证信息
      localStorage.removeItem('token');
      localStorage.removeItem('refresh_token');
      localStorage.removeItem('username');
      setUser(null);
      message.success('已退出登录');
    }
  };

  const value: AuthContextType = {
    user,
    isAuthenticated: !!user,
    login,
    logout,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};