import axios from 'axios';

// 配置基础URL - 从环境变量读取，默认使用当前访问的域名和端口
const BASE_URL = process.env.REACT_APP_API_BASE_URL || (typeof window !== 'undefined' ? window.location.origin : 'http://localhost:8089');
const API_BASE_URL = `${BASE_URL}/api`;

// 创建统一的API客户端
const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// 请求拦截器 - 添加token
apiClient.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// 响应拦截器 - 处理错误和token刷新
apiClient.interceptors.response.use(
  (response) => {
    return response;
  },
  async (error) => {
    const originalRequest = error.config;
    
    // 只有在API请求返回401时才尝试刷新token（被动刷新）
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      
      const refreshToken = localStorage.getItem('refresh_token');
      if (refreshToken) {
        try {
          const response = await axios.post(`${BASE_URL}/refresh`, {
            refresh_token: refreshToken
          });
          
          if (response.data && response.data.access_token) {
            localStorage.setItem('token', response.data.access_token);
            if (response.data.refresh_token) {
              localStorage.setItem('refresh_token', response.data.refresh_token);
            }
            
            // 重新发送原始请求
            originalRequest.headers.Authorization = `Bearer ${response.data.access_token}`;
            return apiClient(originalRequest);
          }
        } catch (refreshError) {
          // 刷新失败，清除所有token并跳转登录
          localStorage.removeItem('token');
          localStorage.removeItem('refresh_token');
          window.location.href = '/login';
          return Promise.reject(refreshError);
        }
      } else {
        // 没有refresh_token，直接跳转登录
        localStorage.removeItem('token');
        localStorage.removeItem('refresh_token');
        window.location.href = '/login';
      }
    }
    
    // 对于登录接口的401错误，直接返回后端错误信息
    if (error.config?.url?.includes('/login')) {
      return Promise.reject(error.response?.data || error);
    }
    
    return Promise.reject(error.response?.data || error);
  }
);

// 认证相关API
export const authAPI = {
  // 管理员登录
  login: async (username: string, password: string): Promise<any> => {
    return await axios.post(`${BASE_URL}/login`, { username, password });
  },

  // 退出登录
  logout: async (): Promise<any> => {
    return await apiClient.post('/api/logout');
  },

  // 修改密码
  modifyPassword: async (oldPassword: string, newPassword: string, repeatPassword: string): Promise<any> => {
    return await apiClient.post('/api/sys/modify', {
      old_password: oldPassword,
      new_password: newPassword,
      repeat_password: repeatPassword
    });
  }
};

// 用户管理API
export const userAPI = {
  // 获取用户列表
  getUsers: async (page?: number, limit?: number) => {
    const params = new URLSearchParams();
    if (page) params.append('page', page.toString());
    if (limit) params.append('limit', limit.toString());
    
    const url = params.toString() ? `/api/users?${params.toString()}` : '/api/users';
    return await apiClient.get(url);
  },

  // 添加用户
  addUser: async (userData: {
    username: string;
    password: string;
    owner: string;
    totp_enabled: boolean;
  }) => {
    return await apiClient.post('/api/users', {
      username: userData.username,
      password: userData.password,
      owner: userData.owner,
      totp_enabled: userData.totp_enabled ? "true" : "false"
    });
  },

  // 修改用户密码
  changeUserPassword: async (userData: {
    username: string;
    password: string;
  }) => {
    return await apiClient.put('/api/users', {
      username: userData.username,
      password: userData.password
    });
  },

  // 删除用户
  deleteUser: async (username: string) => {
    return await apiClient.delete('/api/users', {
      data: { username }
    });
  },

  // 管理TOTP（开启/关闭）
  manageTOTP: async (userData: {
    username: string;
    totp_enabled: boolean;
  }) => {
    return await apiClient.post('/api/users/totp', {
      username: userData.username,
      totp_enabled: userData.totp_enabled
    });
  },

  // 重置TOTP
  resetTOTP: async (username: string) => {
    return await apiClient.put('/api/users/totp', {
      username
    });
  },

  // 生成TOTP二维码
  generateTOTP: async (username: string) => {
    const response = await apiClient.post('/api/users/totp/generate', {
      username
    });
    return response.data;
  }
};

// 系统统计API
export const statsAPI = {
  // 获取仪表盘统计信息
  getDashboardStats: async () => {
    return await apiClient.get('/api/dashboard/information');
  },

  // 获取认证日志
  getAuthLogs: async (params?: {
    page?: number;
    limit?: number;
    username?: string;
    protocol?: string;
    start_time?: string;
    end_time?: string;
  }) => {
    const queryParams = new URLSearchParams();
    
    // 设置默认值
    queryParams.append('page', (params?.page || 1).toString());
    queryParams.append('limit', (params?.limit || 20).toString());
    
    // 添加可选参数
    if (params?.username) queryParams.append('username', params.username);
    if (params?.protocol) queryParams.append('protocol', params.protocol);
    if (params?.start_time) queryParams.append('start_time', params.start_time);
    if (params?.end_time) queryParams.append('end_time', params.end_time);
    
    return await apiClient.get(`/api/auth/information?${queryParams.toString()}`);
  },

  // 获取操作日志
  getOperationLogs: async (params?: {
    page?: number;
    limit?: number;
    username?: string;
    user_type?: string;
    operation?: string;
    start_time?: string;
    end_time?: string;
  }) => {
    const queryParams = new URLSearchParams();
    
    // 设置默认值
    queryParams.append('page', (params?.page || 1).toString());
    queryParams.append('limit', (params?.limit || 20).toString());
    
    // 添加可选参数
    if (params?.username) queryParams.append('username', params.username);
    if (params?.user_type) queryParams.append('user_type', params.user_type);
    if (params?.operation) queryParams.append('operation', params.operation);
    if (params?.start_time) queryParams.append('start_time', params.start_time);
    if (params?.end_time) queryParams.append('end_time', params.end_time);
    
    return await apiClient.get(`/api/sys/operationlogs?${queryParams.toString()}`);
  }
};

