import React, { useState, useEffect } from 'react';
import {
  Layout,
  Menu,
  Card,
  Statistic,
  Table,
  Button,
  Avatar,
  Dropdown,
  Space,
  Row,
  Col,
  Typography,
  Tag,
  DatePicker,
  Input,
  Modal,
  Form,
  Switch,
  Select,
  message,
  Tabs,
  FormInstance
} from 'antd';
import {
  UserOutlined,
  LogoutOutlined,
  DashboardOutlined,
  TeamOutlined,
  HistoryOutlined,
  SettingOutlined,
  MailOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  ExclamationCircleOutlined,
  SendOutlined,
  InboxOutlined,
  SafetyOutlined,
  FileTextOutlined,
  SearchOutlined,
  ArrowUpOutlined,
  ArrowDownOutlined,
  EditOutlined,
  MenuUnfoldOutlined,
  MenuFoldOutlined,
  QrcodeOutlined
} from '@ant-design/icons';
import { useAuth } from '../contexts/AuthContext';
import { authAPI, statsAPI, userAPI, systemAPI, ipBlockAPI } from '../services/api';
import './Dashboard.css';

const { Header, Sider, Content } = Layout;
const { Title } = Typography;
const { Search } = Input;

// 自定义邮件网关Logo组件
